def get_points_no(self) ->int:
    if not self.points:
        return 0
    return len(self.points)

def get_points_no(self) ->int:
    result = 0

    for track_segment in self.segments:
        result += track_segment.get_points_no()

    return result

def get_points_no(self) ->int:
    result = 0
    for track in self.tracks:
        result += track.get_points_no()
    return result
